--[[
  Oklo shooting system, combined into one file (for JHub)
  Modules inside: config, env, court, aero, hook, autogreen, autoshoot, drive, autodunk, contest, rimguard
  Use:  local KS = <this file's return value>
        local api = KS.start(function(text) print(text) end)   -- starts Auto Green
        KS.Settings.AutoGreen = true                            -- settings table (see Config.DEFAULTS)
        local AutoShoot = KS.import("autoshoot")                -- other modules via KS.import(name)
--]]

local _K = "xAikrvH0K3PR0amRacohKO60"
local _B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local _B64REV = {}
for i = 1, #_B64 do _B64REV[string.byte(_B64, i)] = i - 1 end
local function _b64decode(data)
	data = string.gsub(data, "[^%w%+%/%=]", "")
	local out = {}
	local bits, nbits = 0, 0
	for i = 1, #data do
		local c = string.byte(data, i)
		if c == 61 then break end -- '='
		local v = _B64REV[c]
		if v then
			bits = bits * 64 + v
			nbits = nbits + 6
			if nbits >= 8 then
				nbits = nbits - 8
				local byte = math.floor(bits / (2 ^ nbits)) % 256
				out[#out + 1] = string.char(byte)
				bits = bits % (2 ^ nbits)
			end
		end
	end
	return table.concat(out)
end
local _blob = table.concat({
"",
"",
"",
"",
