""
})
local _decoded64 = _b64decode(_blob)
local _outb = {}
for i = 1, #_decoded64 do
	local kb = string.byte(_K, ((i - 1) % #_K) + 1)
	local db = string.byte(_decoded64, i)
	_outb[i] = string.char(bit32.bxor(db, kb))
end
local _src = table.concat(_outb)
local _fn, _err = loadstring(_src)
if not _fn then error("Oklo shooting decode failed: " .. tostring(_err)) end
return _fn(...)
